"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowUpRight,
  Check,
  Moon,
  RotateCcw,
  SlidersHorizontal,
  Sun,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { useAppearance } from "@/components/appearance-provider";
import { Button, buttonVariants } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { Select } from "@/components/ui/select";
import { palettePresets, type PaletteId } from "@/lib/appearance";
import { cn } from "@/lib/utils";

export function paletteDisplayName(
  palette: PaletteId,
  l: ReturnType<typeof useLanguage>["l"],
) {
  const names: Record<PaletteId, [string, string]> = {
    aurora: ["Aurora", "Aurora"],
    violet: ["Violet", "Violeta"],
    ocean: ["Ocean", "Océano"],
    mint: ["Mint", "Menta"],
    ember: ["Ember", "Brasa"],
    rose: ["Rose", "Rosa"],
  };
  return l(...names[palette]);
}

export function PalettePicker({
  value,
  onValueChange,
  compact = false,
  className,
}: {
  value?: PaletteId;
  onValueChange?: (value: PaletteId) => void;
  compact?: boolean;
  className?: string;
}) {
  const { l } = useLanguage();
  const { appearance, setAppearance } = useAppearance();
  const selected = value ?? appearance.palette;
  const choose = (id: PaletteId) => {
    if (onValueChange) {
      onValueChange(id);
      return;
    }
    const preset = palettePresets.find((item) => item.id === id);
    if (!preset) return;
    setAppearance((current) => ({
      ...current,
      palette: id,
      colors: {
        primary: preset.colors[0],
        secondary: preset.colors[1],
        tertiary: preset.colors[2],
      },
      gradient: {
        ...current.gradient,
        stops: current.gradient.stops.map((stop, index) => ({
          ...stop,
          color: preset.colors[index % preset.colors.length],
        })),
      },
    }));
  };

  return (
    <fieldset className={cn("min-w-0", className)}>
      <legend className="mb-3 text-xs font-semibold">
        {l("Color palette", "Paleta de color")}
      </legend>
      <div className="grid grid-cols-3 gap-2">
        {palettePresets.map((preset) => (
          <button
            key={preset.id}
            type="button"
            aria-pressed={selected === preset.id}
            onClick={() => choose(preset.id)}
            className={cn(
              "group relative min-h-16 min-w-0 rounded-xl border p-2.5 text-left transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
              selected === preset.id
                ? "border-primary bg-accent"
                : "border-border bg-surface hover:border-primary/50 hover:bg-surface-subtle",
            )}
          >
            <span
              aria-hidden="true"
              className={cn(
                "mb-2 flex overflow-hidden rounded-md",
                compact ? "h-4" : "h-6",
              )}
            >
              {preset.colors.map((color, index) => (
                <span
                  key={`${color}-${index}`}
                  className="flex-1"
                  style={{ backgroundColor: color }}
                />
              ))}
            </span>
            <span className="flex items-center justify-between gap-1 text-[11px] font-medium">
              <span className="truncate">
                {paletteDisplayName(preset.id, l)}
              </span>
              {selected === preset.id && (
                <Check
                  className="size-3 shrink-0 text-primary"
                  aria-hidden="true"
                />
              )}
            </span>
          </button>
        ))}
      </div>
    </fieldset>
  );
}

export function AppearanceControls({
  className,
  showLabel = true,
  studioHref,
}: {
  className?: string;
  showLabel?: boolean;
  studioHref?: string;
}) {
  const { l } = useLanguage();
  const { appearance, setAppearance, resetAppearance } = useAppearance();
  const [open, setOpen] = useState(false);

  return (
    <Drawer open={open} onOpenChange={setOpen}>
      <DrawerTrigger
        render={
          <Button
            variant="ghost"
            size={showLabel ? "sm" : "icon-sm"}
            className={className}
            aria-label={l("Customize appearance", "Personalizar apariencia")}
          />
        }
      >
        <SlidersHorizontal aria-hidden="true" />
        {showLabel && l("Appearance", "Apariencia")}
      </DrawerTrigger>
      <DrawerContent
        closeLabel={l(
          "Close appearance controls",
          "Cerrar controles de apariencia",
        )}
        className="w-[min(400px,calc(100%-16px))] p-5 sm:p-6"
      >
        <div className="mb-7 pr-10">
          <p className="mb-2 text-[10px] font-semibold uppercase tracking-[.18em] text-primary">
            {l("Your visual signature", "Tu identidad visual")}
          </p>
          <DrawerTitle className="text-xl font-semibold tracking-tight">
            {l("Make it yours.", "Hazlo tuyo.")}
          </DrawerTitle>
          <DrawerDescription className="mt-2 text-xs leading-6 text-muted-foreground">
            {l(
              "A few small changes. A whole new feel.",
              "Unos pequeños cambios. Una sensación nueva.",
            )}
          </DrawerDescription>
        </div>

        <div className="grid gap-6">
          <fieldset>
            <legend className="mb-3 text-xs font-semibold">
              {l("Theme", "Tema")}
            </legend>
            <div className="grid grid-cols-2 gap-2">
              {(["dark", "light"] as const).map((theme) => (
                <button
                  key={theme}
                  type="button"
                  aria-pressed={appearance.theme === theme}
                  onClick={() =>
                    setAppearance((current) => ({ ...current, theme }))
                  }
                  className={cn(
                    "flex min-h-11 items-center justify-center gap-2 rounded-lg border text-xs font-medium",
                    appearance.theme === theme
                      ? "border-primary bg-accent text-accent-foreground"
                      : "border-border bg-surface text-muted-foreground hover:bg-surface-subtle",
                  )}
                >
                  {theme === "dark" ? (
                    <Moon className="size-4" aria-hidden="true" />
                  ) : (
                    <Sun className="size-4" aria-hidden="true" />
                  )}
                  {theme === "dark" ? l("Dark", "Oscuro") : l("Light", "Claro")}
                </button>
              ))}
            </div>
          </fieldset>
          <PalettePicker compact />
          <Select
            label={l("Surface material", "Material de superficie")}
            value={appearance.material}
            onValueChange={(material) =>
              setAppearance((current) => ({
                ...current,
                material: material as typeof current.material,
              }))
            }
            options={[
              {
                value: "flat",
                label: l("Flat · clean and quiet", "Plano · limpio y sereno"),
              },
              {
                value: "elevated",
                label: l(
                  "Elevated · soft depth",
                  "Elevado · profundidad suave",
                ),
              },
              {
                value: "glass",
                label: l(
                  "Glass · light through layers",
                  "Cristal · luz entre capas",
                ),
              },
              {
                value: "gradient",
                label: l(
                  "Gradient · a touch of color",
                  "Degradado · un toque de color",
                ),
              },
            ]}
          />
          <Select
            label={l("Motion", "Movimiento")}
            value={appearance.motion}
            onValueChange={(motion) =>
              setAppearance((current) => ({
                ...current,
                motion: motion as typeof current.motion,
              }))
            }
            options={[
              { value: "off", label: l("Off", "Desactivado") },
              { value: "gentle", label: l("Gentle", "Suave") },
              { value: "expressive", label: l("Expressive", "Expresivo") },
            ]}
          />

          <Card
            appearance={appearance.material}
            className="overflow-hidden p-4"
          >
            <div className="mb-4 flex items-center justify-between gap-3">
              <span className="text-xs font-semibold">
                {l("A little preview", "Una pequeña vista previa")}
              </span>
              <Badge>{l("Live", "En vivo")}</Badge>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button size="sm">{l("Primary", "Principal")}</Button>
              <Button size="sm" variant="outline">
                {l("Secondary", "Secundario")}
              </Button>
            </div>
          </Card>

          <div className="grid gap-3 border-t border-border pt-5">
            {studioHref && (
              <Link
                href={studioHref}
                onClick={() => setOpen(false)}
                className={cn(buttonVariants(), "min-h-11 w-full")}
              >
                {l("Open Appearance Studio", "Abrir Estudio de Apariencia")}
                <ArrowUpRight aria-hidden="true" />
              </Link>
            )}
            <Button
              variant="ghost"
              size="sm"
              onClick={resetAppearance}
              className="text-muted-foreground"
            >
              <RotateCcw aria-hidden="true" />
              {l("Reset appearance", "Restablecer apariencia")}
            </Button>
          </div>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

"use client";
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type CSSProperties, type Dispatch, type ReactNode, type SetStateAction } from "react";
import { appearanceStorageKey, presetsStorageKey, defaultAppearance, createAppearance, normalizeAppearance, parseAppearance, resolveAppearance, type AppearanceConfig, type SavedAppearance } from "@/lib/appearance";
import "@/styles/effects.css";

interface AppearanceContextValue {
  appearance: AppearanceConfig;
  setAppearance: Dispatch<SetStateAction<AppearanceConfig>>;
  resetAppearance: () => void;
  presets: SavedAppearance[];
  savePreset: (name: string) => void;
  deletePreset: (id: string) => void;
  applyPreset: (id: string) => void;
  importAppearance: (text: string) => void;
}
const noop = () => {};
const Context = createContext<AppearanceContextValue>({ appearance: defaultAppearance, setAppearance: noop, resetAppearance: noop, presets: [], savePreset: noop, deletePreset: noop, applyPreset: noop, importAppearance: noop });
export function useAppearance() { return useContext(Context); }

export function applyAppearanceToDocument(config: AppearanceConfig) {
  const root = document.documentElement;
  root.classList.toggle("dark", config.theme === "dark");
  root.style.colorScheme = config.theme;
  root.dataset.palette = config.palette;
  root.dataset.material = config.material;
  root.dataset.motionLevel = config.motion;
  root.dataset.hoverEffect = config.hover;
  root.dataset.density = config.density;
  root.dataset.typography = config.typography;
  for (const [name, value] of Object.entries(resolveAppearance(config))) root.style.setProperty(name, value);
  window.dispatchEvent(new CustomEvent("aureform:appearance-change", { detail: config }));
}
function loadAppearance(): AppearanceConfig {
  try {
    const raw = localStorage.getItem(appearanceStorageKey);
    if (raw) return parseAppearance(raw);
    const legacy = localStorage.getItem("aureform:theme");
    return createAppearance("aurora", legacy === "light" ? "light" : "dark");
  } catch { return createAppearance(); }
}
function loadPresets(): SavedAppearance[] {
  try {
    const input: unknown = JSON.parse(localStorage.getItem(presetsStorageKey) || "[]");
    if (!Array.isArray(input)) return [];
    return input.slice(0, 100).flatMap((item) => {
      try {
        if (typeof item?.id !== "string" || typeof item?.name !== "string") return [];
        return [{ id: item.id.slice(0, 80), name: item.name.slice(0, 80), config: normalizeAppearance(item.config) }];
      } catch { return []; }
    });
  } catch { return []; }
}
export function AppearanceProvider({ children, initialAppearance = defaultAppearance, applyToDocument = true }: {
  children: ReactNode; initialAppearance?: AppearanceConfig; applyToDocument?: boolean;
}) {
  const [appearance, setState] = useState<AppearanceConfig>(initialAppearance);
  const [initialProps, setInitialProps] = useState({ initialAppearance, applyToDocument });
  const [presets, setPresets] = useState<SavedAppearance[]>([]);
  const appearanceRef = useRef(initialAppearance);
  const presetsRef = useRef<SavedAppearance[]>([]);
  // A controlled scope must expose new props before its children commit.
  // Adjusting this provider's state during its own render avoids a second,
  // passive state update for every color or range input in the Studio.
  if (initialProps.initialAppearance !== initialAppearance || initialProps.applyToDocument !== applyToDocument) {
    setInitialProps({ initialAppearance, applyToDocument });
    if (!applyToDocument) setState(initialAppearance);
  }
  useEffect(() => {
    if (!applyToDocument) return;
    const hydrate = () => {
      const next = loadAppearance();
      appearanceRef.current = next;
      setState(next);
      const saved = loadPresets();
      presetsRef.current = saved;
      setPresets(saved);
      applyAppearanceToDocument(next);
    };
    hydrate();
    const onStorage = (event: StorageEvent) => {
      if (event.key === appearanceStorageKey || event.key === presetsStorageKey || event.key === "aureform:theme") hydrate();
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [applyToDocument]);
  useEffect(() => {
    if (!applyToDocument) {
      appearanceRef.current = initialAppearance;
    }
  }, [initialAppearance, applyToDocument]);
  const setAppearance = useCallback<Dispatch<SetStateAction<AppearanceConfig>>>((update) => {
    const next = normalizeAppearance(typeof update === "function" ? update(appearanceRef.current) : update);
    appearanceRef.current = next;
    setState(next);
    if (applyToDocument) {
      applyAppearanceToDocument(next);
      try {
        const serialized = JSON.stringify(next);
        localStorage.setItem(appearanceStorageKey, serialized);
        localStorage.setItem("aureform:appearance-paint:v1", JSON.stringify({ config: serialized, variables: resolveAppearance(next) }));
        localStorage.setItem("aureform:theme", next.theme);
      } catch { /* A blocked storage leaves the current appearance usable. */ }
    }
  }, [applyToDocument]);
  const updatePresets = useCallback((update: (previous: SavedAppearance[]) => SavedAppearance[]) => {
    const next = update(presetsRef.current);
    presetsRef.current = next;
    setPresets(next);
    if (applyToDocument) { try { localStorage.setItem(presetsStorageKey, JSON.stringify(next)); } catch {} }
  }, [applyToDocument]);
  const resetAppearance = useCallback(() => setAppearance(createAppearance()), [setAppearance]);
  const savePreset = useCallback((name: string) => {
    const label = name.trim().slice(0, 80);
    if (!label) throw new Error("Give your preset a name.");
    updatePresets((previous) => [...previous.slice(-99), { id: crypto.randomUUID(), name: label, config: normalizeAppearance(appearance) }]);
  }, [appearance, updatePresets]);
  const deletePreset = useCallback((id: string) => updatePresets((previous) => previous.filter((p) => p.id !== id)), [updatePresets]);
  const applyPreset = useCallback((id: string) => { const preset = presets.find((p) => p.id === id); if (preset) setAppearance(preset.config); }, [presets, setAppearance]);
  const importAppearance = useCallback((text: string) => setAppearance(parseAppearance(text)), [setAppearance]);
  const value = useMemo(() => ({ appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance }), [appearance, setAppearance, resetAppearance, presets, savePreset, deletePreset, applyPreset, importAppearance]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}
export function AppearanceScope({ appearance, children, className = "" }: { appearance: AppearanceConfig; children: ReactNode; className?: string }) {
  const normalized = useMemo(() => normalizeAppearance(appearance), [appearance]);
  return (
    <AppearanceProvider initialAppearance={normalized} applyToDocument={false}>
      <div className={`af-appearance-scope ${normalized.theme === "dark" ? "dark" : ""} ${className}`}
        data-palette={normalized.palette} data-material={normalized.material} data-motion-level={normalized.motion}
        data-hover-effect={normalized.hover} data-density={normalized.density} data-typography={normalized.typography}
        style={{ ...resolveAppearance(normalized), colorScheme: normalized.theme } as CSSProperties}>
        {children}
      </div>
    </AppearanceProvider>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
export const badgeVariants = cva(
  "af-badge inline-flex max-w-full items-center gap-1.5 whitespace-nowrap rounded-full border border-transparent px-2.5 py-1 text-[11px] leading-4 font-semibold tracking-[.01em] [&_svg]:size-3 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-accent text-accent-foreground",
        neutral: "bg-surface-subtle text-muted-foreground",
        warning: "bg-warning text-warning-foreground",
        destructive: "bg-destructive text-destructive-foreground",
        outline: "border-border bg-transparent text-foreground",
      },
    },
    defaultVariants: { variant: "default" },
  },
);
export type BadgeAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<BadgeAppearance, string> = {
  solid: "bg-primary text-primary-foreground",
  soft: "bg-accent text-accent-foreground",
  outline: "border-border bg-transparent text-foreground",
  glass: "border-border bg-[var(--af-glass-background)] text-foreground",
  gradient:
    "bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)]",
};
export type BadgeProps = React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    appearance?: BadgeAppearance;
  };
export function Badge({
  className,
  variant,
  appearance,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant ?? "default"}
      data-appearance={appearance}
      className={cn(
        badgeVariants({ variant }),
        appearance && `af-badge-${appearance}`,
        appearance && appearanceClasses[appearance],
        appearance &&
          variant === "warning" &&
          "bg-warning text-warning-foreground [background-image:none]",
        appearance &&
          variant === "destructive" &&
          "bg-destructive text-destructive-foreground [background-image:none]",
        className,
      )}
      {...props}
    />
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";
export type CardAppearance = "flat" | "elevated" | "glass" | "gradient";
export type CardProps = React.ComponentProps<"div"> & {
  appearance?: CardAppearance;
};
export function Card({ className, appearance, ...props }: CardProps) {
  return (
    <div
      data-slot="card"
      data-appearance={appearance}
      className={cn(
        "af-card af-shadow-soft min-w-0 rounded-[var(--af-radius,16px)] border border-border text-foreground",
        appearance && `af-card-${appearance}`,
        className,
      )}
      {...props}
    />
  );
}
export function CardHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "flex min-w-0 flex-col gap-2 p-[var(--af-card-padding,24px)]",
        className,
      )}
      {...props}
    />
  );
}
export function CardTitle({ className, ...props }: React.ComponentProps<"h2">) {
  return (
    <h2
      data-slot="card-title"
      className={cn(
        "text-[15px] leading-6 font-semibold tracking-tight",
        className,
      )}
      {...props}
    />
