    "--af-card-padding": c.density === "compact" ? "18px" : "24px",
    "--font-display": c.typography === "editorial" ? 'var(--font-instrument, Georgia, serif)' : 'var(--font-manrope, "Manrope", system-ui, sans-serif)',
